 12345678解法二：时间复杂度O(N)，空间复杂度O(1) var fib = function(n) {
    // 动规状态转移中，当前结果只依赖前两个元素的结果，所以只要两个变量代替dp数组记录状态过程。将空间复杂度降到O(1)
    let pre1 = 1
    let pre2 = 0
    let temp
    if (n === 0) return 0
    if (n === 1) return 1
    for(let i = 2; i <= n; i++) {
        temp = pre1
        pre1 = pre1 + pre2
        pre2 = temp
    }
    return pre1
};
 1234567891011121314 TypeScript function fib(n: number): number {
    /**
        dp[i]: 第i个斐波那契数
        dp[0]: 0;
        dp[1]：1；
        ...
        dp[i] = dp[i - 1] + dp[i - 2];
     */
    const dp: number[] = [];
    dp[0] = 0;
    dp[1] = 1;
    for (let i = 2; i <= n; i++) {
        dp[i] = dp[i - 1] + dp[i - 2];
    }
    return dp[n];
};
 12345678910111213141516 C 动态规划: int fib(int n){
    //当n <= 1时，返回n
    if(n <= 1)
        return n;
    //动态开辟一个int数组，大小为n+1
    int *dp = (int *)malloc(sizeof(int) * (n + 1));
    //设置0号位为0，1号为为1
    dp[0] = 0;
    dp[1] = 1;

    //从前向后遍历数组(i=2; i <= n; ++i),下标为n时的元素为dp[i-1] + dp[i-2]
    int i;
    for(i = 2; i <= n; ++i) {
        dp[i] = dp[i - 1] + dp[i - 2];
    }
    return dp[n];
}
 1234567891011121314151617递归实现： int fib(int n){
    //若n小于等于1，返回n
    if(n <= 1)
        return n;
    //否则返回fib(n-1) + fib(n-2)
    return fib(n-1) + fib(n-2);
}
 1234567 Rust 动态规划: impl Solution {
    pub fn fib(n: i32) -> i32 {
        if n <= 1 {
            return n;
        }
        let n = n as usize;
        let mut dp = vec![0; n + 1];
        dp[1] = 1;
        for i in 2..=n {
            dp[i] = dp[i - 2] + dp[i - 1];
        }
        dp[n]
    }
}
