 1234567891011121314151617181920212223242526272829303132版本三：空间优化版本 func maxProfit(k int, prices []int) int {
    n := len(prices)
    // k次交易，2 * k种状态
    // 状态从1开始计算，避免判断
    // 奇数时持有(保持或买入)
    // 偶数时不持有(保持或卖出)
    dp := make([][]int, 2)
    dp[0] = make([]int, k * 2 + 1)
    dp[1] = make([]int, k * 2 + 1)

    // 奇数状态时持有，i += 2
    for i := 1; i <= k * 2; i += 2 {
        dp[0][i] = -prices[0]
    }

    for i := 1; i < len(prices); i++ {
        for j := 1; j <= k * 2; j++ {
            if j % 2 == 1 {
                dp[i % 2][j] = max(dp[(i - 1) % 2][j], dp[(i - 1) % 2][j - 1] - prices[i])
            } else {
                dp[i % 2][j] = max(dp[(i - 1) % 2][j], dp[(i - 1) % 2][j - 1] + prices[i])
            }
        }
    }

    return dp[(n - 1) % 2][k * 2]
}

