                if i % 2 == 1 {
                    // 买入
                    dp[i] = dp[i].max(dp[i - 1] - p);
                    continue;
                }
                // 卖出
                dp[i] = dp[i].max(dp[i - 1] + p);
            }
        }

        dp[2 * k as usize]
    }
}
