    pub fn count_substrings(s: String) -> i32 {
        let mut res = 0;
        for i in 0..s.len() {
            res += Self::extend(&s, i, i, s.len());
            res += Self::extend(&s, i, i + 1, s.len());
        }
        res
    }

    fn extend(s: &str, mut i: usize, mut j: usize, len: usize) -> i32 {
        let mut res = 0;
        while i < len && j < len && s[i..=i] == s[j..=j] {
            res += 1;
            i = i.wrapping_sub(1);
            j += 1;
        }
        res
    }
}
